# Close a period, fixing its due-total; refuses one not on the sheet or already closed. Responds with the sheet's periods.
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriods
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Closes the period, fixing its due-total now: the due of the counted (OPEN and SETTLED, but not a held person's
 * OPEN) claims dated in it (a
 * claim with no rate adds nothing). Refuses a period not on the sheet or already closed.
 */
public class ClosePeriod {
    public void close(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
            @RequestParam("user") String user, Periods periods, Claims claims, People people, Rates rates, Settings settings,
            SheetClock clock, Audit audit)
            throws InvalidPeriodException {
        Period found = periods.find(sheet, period);
        if (found == null) {
            throw new InvalidPeriodException("There is no period named " + period);
        }
        if (found.closed()) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Rate> sheetRates = rates.list(sheet);
        BigDecimal floor = settings.floor(sheet);
        Late late = settings.late(sheet, clock.today(sheet));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.list(sheet)) {
            LocalDate date = LocalDate.parse(claim.date());
            Person person = byId.get(claim.person());
            if (person == null || !claim.counts(person.held()) || date.isBefore(from) || date.isAfter(to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            total = due == null ? total : total.add(due);
        }
        if (!periods.close(sheet, period, total)) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        audit.record("PERIOD_CLOSED sheet=" + sheet + " by=" + user + " period=" + period + " total="
                + total.toPlainString());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPeriod {
    public void handle(@Parameter InvalidPeriodException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.period;

/** The period has no name or a name already on the sheet, a bad date, a to-date before its from-date, or overlaps another period. */
public class InvalidPeriodException extends Exception {
    public InvalidPeriodException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A validated period body: a name and a from and to date, inclusive, the from on or before the to. */
public record PeriodInput(String name, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.period;

/**
 * A period on a sheet: its name and its from and to date (yyyy-MM-dd), inclusive, whether it is closed, and its
 * due-total fixed when closed (two decimals; null while open).
 */
public record Period(String name, String from, String to, boolean closed, String closedTotal) {
}
package net.officefloor.hq.app.period;

/** Body of POST /api/sheets/{sheet}/periods; a blank from-date is the sheet's today. */
public record PeriodRequest(String name, String from, String to) {
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("name"),
            rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString(),
            rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null : rs.getBigDecimal("closed_total").toPlainString());

    private static final String COLUMNS = "SELECT name, from_date, to_date, closed, closed_total FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> list(String sheet) {
        return jdbc.query(COLUMNS + " WHERE sheet = ? ORDER BY from_date", ROW, sheet);
    }

    /** The sheet's period of the name, or null when there is none. */
    public Period find(String sheet, String name) {
        List<Period> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND name = ?", ROW, sheet, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the date falls inside a closed period of the sheet. */
    public boolean closedOn(String sheet, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Whether the sheet has a period of the name. */
    public boolean named(String sheet, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet = ? AND name = ?", Integer.class,
                sheet, name);
        return n != null && n > 0;
    }

    /** Whether any period on the sheet shares a date with the inclusive range. */
    public boolean overlaps(String sheet, PeriodInput input) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND from_date <= ? AND to_date >= ?", Integer.class,
                sheet, Date.valueOf(input.to()), Date.valueOf(input.from()));
        return n != null && n > 0;
    }

    public void add(String sheet, PeriodInput input) {
        jdbc.update("INSERT INTO period (sheet, name, from_date, to_date) VALUES (?, ?, ?, ?)", sheet, input.name(),
                Date.valueOf(input.from()), Date.valueOf(input.to()));
    }

    /** Closes the period with its due-total fixed; false when it was already closed (or is gone). */
    public boolean close(String sheet, String name, BigDecimal total) {
        return jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed",
                total, sheet, name) == 1;
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with every period on the sheet. */
public class RespondWithPeriods {
    public void respond(@PathVariable("sheet") String sheet, Periods periods, ObjectResponse<List<Period>> response) {
        response.send(periods.list(sheet));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Adds the period, refusing a name already on the sheet or dates that overlap another period. */
public class SavePeriod {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val PeriodInput input,
            Periods periods, Audit audit) throws InvalidPeriodException {
        if (periods.named(sheet, input.name())) {
            throw new InvalidPeriodException("There is already a period named " + input.name());
        }
        if (periods.overlaps(sheet, input)) {
            throw new InvalidPeriodException("A period may not overlap another period");
        }
        periods.add(sheet, input);
        audit.record("PERIOD_ADDED sheet=" + sheet + " by=" + user + " period=" + input.name() + " from="
                + input.from() + " to=" + input.to());
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePeriod {
    public void validate(@PathVariable("sheet") String sheet, @RequestBody PeriodRequest request, SheetClock clock,
            Out<PeriodInput> body) throws InvalidPeriodException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String from = request == null || request.from() == null ? "" : request.from().trim();
        String to = request == null || request.to() == null ? "" : request.to().trim();
        if (name.isEmpty()) {
            throw new InvalidPeriodException("A period needs a name");
        }
        if (name.length() > 200) {
            throw new InvalidPeriodException("A period's name is at most 200 characters");
        }
        LocalDate start;
        LocalDate end;
        try {
            start = from.isEmpty() ? clock.today(sheet) : LocalDate.parse(from);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("Not a valid from-date: " + from);
        }
        try {
            end = LocalDate.parse(to);
        } catch (DateTimeParseException e) {
